namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string CourseCode { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Instructor { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = "";
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{1}\d{8}$", ErrorMessage = "Student ID must be a letter followed by 8 digits (e.g., S12345678).")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, quantities, shapes, and patterns." },
            new() { Id = 3, Name = "English", Code = "ENG", Description = "Study of English language, literature, and writing." },
            new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Programming", CourseCode = "CS 101", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, data structures, and object-oriented programming. No prior experience required.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", Instructor = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has over 15 years of experience teaching introductory programming. She holds a Ph.D. in Computer Science from MIT and has published extensively on CS education.", DepartmentId = 1, DepartmentCode = "CS", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", CourseCode = "CS 201", Description = "Study of fundamental data structures including arrays, linked lists, trees, graphs, and hash tables. Covers algorithm design and analysis with Big-O notation.", Credits = 4, Schedule = "TTh 1:00–2:20 PM", Instructor = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez is an expert in algorithm design and competitive programming. He earned his Ph.D. from Stanford and previously worked at Google Research.", DepartmentId = 1, DepartmentCode = "CS", IsFeatured = false },
            new() { Id = 3, Title = "Database Systems", CourseCode = "CS 340", Description = "Introduction to database design, SQL, normalization, transaction management, and NoSQL databases. Includes a semester-long project building a full-stack application.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", Instructor = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez specializes in distributed database systems. She spent a decade in industry at Oracle before joining academia.", DepartmentId = 1, DepartmentCode = "CS", IsFeatured = false },
            new() { Id = 4, Title = "Artificial Intelligence", CourseCode = "CS 440", Description = "Explore the principles of artificial intelligence including search, knowledge representation, machine learning, neural networks, and natural language processing.", Credits = 3, Schedule = "TTh 9:30–10:50 AM", Instructor = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has over 15 years of experience teaching introductory programming. She holds a Ph.D. in Computer Science from MIT and has published extensively on CS education.", DepartmentId = 1, DepartmentCode = "CS", IsFeatured = true },

            // Mathematics
            new() { Id = 5, Title = "Calculus I", CourseCode = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics. Graphing calculator required.", Credits = 4, Schedule = "MWF 9:00–9:50 AM", Instructor = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator with a passion for making calculus accessible. He has authored two popular calculus textbooks.", DepartmentId = 2, DepartmentCode = "MATH", IsFeatured = true },
            new() { Id = 6, Title = "Linear Algebra", CourseCode = "MATH 220", Description = "Vectors, matrices, determinants, eigenvalues, and linear transformations. Applications to computer graphics, data science, and engineering.", Credits = 3, Schedule = "TTh 11:00 AM–12:20 PM", Instructor = "Dr. Emily Nakamura", InstructorBio = "Dr. Nakamura researches applied linear algebra and numerical methods. She holds a joint appointment with the Computer Science department.", DepartmentId = 2, DepartmentCode = "MATH", IsFeatured = false },
            new() { Id = 7, Title = "Probability and Statistics", CourseCode = "MATH 360", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis. Emphasizes real-world data analysis.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", Instructor = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator with a passion for making calculus accessible. He has authored two popular calculus textbooks.", DepartmentId = 2, DepartmentCode = "MATH", IsFeatured = false },

            // English
            new() { Id = 8, Title = "College Composition", CourseCode = "ENG 101", Description = "Develop critical reading, thinking, and writing skills. Students compose essays in various rhetorical modes and learn research writing techniques.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", Instructor = "Prof. Diana Wallace", InstructorBio = "Prof. Wallace is a published novelist and essayist who has taught writing at the university level for over 20 years.", DepartmentId = 3, DepartmentCode = "ENG", IsFeatured = false },
            new() { Id = 9, Title = "American Literature", CourseCode = "ENG 250", Description = "Survey of major American literary works from the colonial period to the present, including novels, poetry, drama, and essays.", Credits = 3, Schedule = "TTh 2:00–3:20 PM", Instructor = "Dr. Michael Torres", InstructorBio = "Dr. Torres is a specialist in 20th-century American fiction. His recent book examines the influence of jazz on American modernist literature.", DepartmentId = 3, DepartmentCode = "ENG", IsFeatured = false },
            new() { Id = 10, Title = "Creative Writing Workshop", CourseCode = "ENG 310", Description = "Workshop-based course in fiction and poetry writing. Students draft, revise, and critique original works in a supportive peer environment.", Credits = 3, Schedule = "W 6:00–8:50 PM", Instructor = "Prof. Diana Wallace", InstructorBio = "Prof. Wallace is a published novelist and essayist who has taught writing at the university level for over 20 years.", DepartmentId = 3, DepartmentCode = "ENG", IsFeatured = true },

            // Physics
            new() { Id = 11, Title = "General Physics I", CourseCode = "PHYS 201", Description = "Mechanics, thermodynamics, and waves. Calculus-based introduction to physics with weekly laboratory sessions. Corequisite: MATH 151.", Credits = 4, Schedule = "MWF 8:00–8:50 AM, Lab: F 1:00–3:50 PM", Instructor = "Dr. Alan Petrov", InstructorBio = "Dr. Petrov is an experimental physicist whose research focuses on condensed matter physics. He is known for his engaging lecture demonstrations.", DepartmentId = 4, DepartmentCode = "PHYS", IsFeatured = false },
            new() { Id = 12, Title = "Electricity and Magnetism", CourseCode = "PHYS 202", Description = "Electric fields, circuits, magnetic fields, and electromagnetic waves. Continuation of General Physics I with laboratory component.", Credits = 4, Schedule = "MWF 10:00–10:50 AM, Lab: Th 1:00–3:50 PM", Instructor = "Dr. Lisa Okafor", InstructorBio = "Dr. Okafor's research is in photonics and optical materials. She received the university's Distinguished Teaching Award in 2022.", DepartmentId = 4, DepartmentCode = "PHYS", IsFeatured = false },
            new() { Id = 13, Title = "Modern Physics", CourseCode = "PHYS 310", Description = "Introduction to special relativity, quantum mechanics, atomic structure, and nuclear physics. Explores the revolutionary ideas that transformed our understanding of the universe.", Credits = 3, Schedule = "TTh 3:30–4:50 PM", Instructor = "Dr. Alan Petrov", InstructorBio = "Dr. Petrov is an experimental physicist whose research focuses on condensed matter physics. He is known for his engaging lecture demonstrations.", DepartmentId = 4, DepartmentCode = "PHYS", IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public List<Course> SearchCourses(string? query, int? departmentId)
    {
        var results = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            results = results.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(query))
        {
            var q = query.Trim();
            results = results.Where(c =>
                c.Title.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Contains(q, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request) => true;
}

