arguments.file_text:
@page "/catalog"
@rendermode InteractiveServer

<PageTitle>Course Catalog</PageTitle>

@inject CatalogService CatalogService

<h1>Course Catalog</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search courses..." @bind="searchQuery" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name (@dept.Code)</option>
            }
        </select>
    </div>
</div>

<p class="text-muted">Showing @filteredCourses.Count course(s)</p>

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Credits</th>
                    <th>Department</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in filteredCourses)
                {
                    <tr>
                        <td>@course.CourseCode</td>
                        <td>@course.Title</td>
                        <td>@course.Credits</td>
                        <td>@course.DepartmentCode</td>
                        <td>@course.Instructor</td>
                        <td><a href="/course/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();
    private string _searchQuery = "";
    private int _selectedDepartmentId;

    private string searchQuery
    {
        get => _searchQuery;
        set { _searchQuery = value; UpdateResults(); }
    }

    private int selectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; UpdateResults(); }
    }

    [SupplyParameterFromQuery(Name = "department")]
    public int? InitialDepartmentId { get; set; }

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        if (InitialDepartmentId.HasValue)
        {
            _selectedDepartmentId = InitialDepartmentId.Value;
        }
        UpdateResults();
    }

    private void UpdateResults()
    {
        int? deptFilter = _selectedDepartmentId > 0 ? _selectedDepartmentId : null;
        filteredCourses = CatalogService.SearchCourses(
            string.IsNullOrWhiteSpace(_searchQuery) ? null : _searchQuery,
            deptFilter);
    }
}

@page "/enroll"

<PageTitle>Enrollment Request</PageTitle>

@inject CatalogService CatalogService

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@(CatalogService.GetCourse(Model.CourseId)?.Title)</strong> has been received.</p>
        <a href="/catalog" class="btn btn-primary">Back to Catalog</a>
    </div>
}
else
{
    <p class="text-muted">Fill out the form below to submit an enrollment request.</p>

    <div class="row">
        <div class="col-md-6">
            <EditForm Model="Model" method="post" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
                <DataAnnotationsValidator />
                <AntiforgeryToken />
                <ValidationSummary class="text-danger" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Student Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                    <ValidationMessage For="() => Model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" placeholder="S12345678" @bind-Value="Model.StudentId" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                        <option value="0">-- Select a course --</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.CourseCode — @course.Title</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> courses = new();
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(Model);
        submitted = true;
    }
}

